n=30
g=[[0]*n for _ in range(n)]
tile_colors=[[3,2,2,3,2],[2,8,8,2,8],[3,2,2,3,2],[2,8,8,2,8],[3,2,2,3,2]]
for tr in range(5):
 for tc in range(5):
  sr,sc=1+7*tr,1+7*tc
  for dr in range(5):
   for dc in range(5):
    r,c=sr+dr,sc+dc
    if r<n and c<n:
     g[r][c]=tile_colors[tr][tc] if 1<=dr<=3 and 1<=dc<=3 else 4
# Paint the aligned minority-color connectors in the gaps.
for r, cols in [(3,[6,7,13,14,20,21]),(10,[13,14]),(17,[6,7,13,14,20,21]),(24,[13,14])]:
 for c in cols: g[r][c]=3 if r in (3,17) else 8
for c, rows, color in [(3,[6,7,13,14],3),(24,[6,7,13,14],3),(10,[13,14,20,21],8),(17,[13,14,20,21],8)]:
 for r in rows:g[r][c]=color
print(len(g), [len(row) for row in g], sorted(set(x for row in g for x in row)))
print(g)

